// ---- index.html (viewport para celular) ----
const htmlPath = path.join(root, 'index.html');
if (fs.existsSync(htmlPath)) {
  let h = fs.readFileSync(htmlPath, 'utf8');
  const before = h;
  if (!/name=["']viewport["']/i.test(h)) {
    h = h.replace(/<head>/i, '<head>\n    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />');
  } else {
    h = h.replace(/(<meta[^>]*name=["']viewport["'][^>]*content=["'])([^"']*)(["'])/i, (m, a, b, c) => (b.includes('viewport-fit') ? m : a + b + ', viewport-fit=cover' + c));
  }
  if (!/theme-color/i.test(h)) h = h.replace(/<\/head>/i, '    <meta name="theme-color" content="#0b0f19" />\n  </head>');
  if (!/o-apito-brand/.test(h)) h = h.replace(/<\/head>/i, '    <!-- o-apito-brand -->\n    <link rel="icon" type="image/png" href="/icon-192.png" />\n    <link rel="apple-touch-icon" href="/icon-192.png" />\n    <link rel="preconnect" href="https://fonts.googleapis.com" />\n    <link href="https://fonts.googleapis.com/css2?family=Saira+Condensed:ital,wght@1,700;1,800;1,900&display=swap" rel="stylesheet" />\n  </head>');
  h = h.replace(/(<meta name="theme-color" content=")#0b0f19(")/i, '$1#000000$2');
  if (h !== before) { backup(htmlPath); fs.writeFileSync(htmlPath, h); console.log('  [ok] index.html (viewport/mobile)'); }
  else console.log('  [mantido] index.html (já preparado)');
} else console.log('  [aviso] index.html não encontrado');

