// ---- Linguagem simples: ajusta textos nos arquivos do projeto que não são reescritos por este script ----
const TEXT_PATCHES = {"src/components/ManagerIncidentModal.tsx":[["INSUBORDINAÇÃO DETECTADA","TÉCNICO PROTESTANDO"],["Relatório do 4º Árbitro: ","Aviso do quarto árbitro: "],["Sua Conduta Disciplinar como Árbitro Principal:","O que você faz?"],["Punir invasão na súmula","Registra na súmula"]],"src/components/MatchStatsSidebar.tsx":[["📊 TELEMETRIA & ESTATÍSTICAS AO VIVO","📊 ESTATÍSTICAS AO VIVO"],["Dados homologados pelo centro de métricas da federação","Dados oficiais da partida"]]};
for (const [rel, pairs] of Object.entries(TEXT_PATCHES)) {
  const p = path.join(root, rel);
  if (!fs.existsSync(p)) { console.log('  [pulado] ' + rel + ' (não encontrado)'); continue; }
  let txt = fs.readFileSync(p, 'utf8');
  let n = 0;
  for (const [from, to] of pairs) { if (to.includes(from) && txt.includes(to)) continue; if (txt.includes(from)) { txt = txt.split(from).join(to); n++; } }
  const dedup = txt.replace(/(import \{ humanize \} from '\.\.\/store\/careerLogic';\r?\n)(\s*import \{ humanize \} from '\.\.\/store\/careerLogic';\r?\n)+/g, '$1');
  if (dedup !== txt) { txt = dedup; n++; }
  if (n > 0) { backup(p); fs.writeFileSync(p, txt); console.log('  [ok] ' + rel + ' (' + n + ' textos simplificados)'); }
  else console.log('  [mantido] ' + rel + ' (nada a ajustar)');
}

